PRECO_MAXIMO = Decimal("99999999.99")


def limpar_valores_invalidos(apps, schema_editor):
    """Apaga preços e coordenadas que o SQLite aceitou fora da faixa.

    Eventos que saíram do feed nunca são reimportados, então esses valores
    ficariam no banco derrubando a listagem. O filtro e o `update` rodam no
    banco, sem ler os valores (ler é justamente o que falha).
    """
    FaixaPreco = apps.get_model("catalogo", "FaixaPreco")
    Local = apps.get_model("catalogo", "Local")
    for campo in ("minimo", "maximo"):
        fora = Q(**{f"{campo}__gt": PRECO_MAXIMO}) | Q(**{f"{campo}__lt": 0})
        FaixaPreco.objects.filter(fora).update(**{campo: None})
    Local.objects.filter(
        Q(latitude__gt=90)
        | Q(latitude__lt=-90)
        | Q(longitude__gt=180)
        | Q(longitude__lt=-180)
    ).update(latitude=None, longitude=None)


